package ports.mekanism.lib.common.data;

import net.minecraft.data.CachedOutput;
import net.minecraft.data.DataGenerator;
import net.minecraft.data.DataProvider;
import org.jetbrains.annotations.Nullable;
import ports.mekanism.lib.registries.IForgeRegistry;

/**
 * Shape of Forge's tag provider for custom registries, so Mekanism's datagen API compiles on Fabric. Mekanism's data
 * is generated by the Forge build only, so running one here fails.
 */
public abstract class ForgeRegistryTagsProvider<T> implements DataProvider {

    protected final DataGenerator generator;
    protected final IForgeRegistry<T> registry;
    protected final String modId;
    @Nullable
    protected final ExistingFileHelper existingFileHelper;

    protected ForgeRegistryTagsProvider(DataGenerator generator, IForgeRegistry<T> registry, String modId, @Nullable ExistingFileHelper existingFileHelper) {
        this.generator = generator;
        this.registry = registry;
        this.modId = modId;
        this.existingFileHelper = existingFileHelper;
    }

    protected abstract void addTags();

    @Override
    public void run(CachedOutput output) {
        throw new UnsupportedOperationException("Mekanism data generation runs on the Forge build");
    }
}
